# Ripe Protocol License: https://github.com/ripe-foundation/ripe-protocol/blob/master/LICENSE.md
# Ripe Foundation (C) 2025

# @version 0.4.3

uses: addys

import contracts.modules.Addys as addys
from ethereum.ercs import IERC20

event VaultPauseModified:
    isPaused: bool

event VaultFundsRecovered:
    asset: indexed(address)
    recipient: indexed(address)
    balance: uint256

# config
isPaused: public(bool)

# balances (may be shares or actual balance)
userBalances: public(HashMap[address, HashMap[address, uint256]]) # user -> asset -> balance
totalBalances: public(HashMap[address, uint256]) # asset -> balance

# user assets (iterable)
userAssets: public(HashMap[address, HashMap[uint256, address]]) # user -> index -> asset
indexOfUserAsset: public(HashMap[address, HashMap[address, uint256]]) # user -> asset -> index
numUserAssets: public(HashMap[address, uint256]) # user -> num assets

# vault assets (iterable)
vaultAssets: public(HashMap[uint256, address]) # index -> asset
indexOfAsset: public(HashMap[address, uint256]) # asset -> index
numAssets: public(uint256) # num assets

MAX_RECOVER_ASSETS: constant(uint256) = 20


@deploy
def __init__(_shouldPause: bool):
    self.isPaused = _shouldPause


###################
# Balance Changes #
###################


# deposit


@internal
def _addBalanceOnDeposit(
    _user: address,
    _asset: address,
    _depositBal: uint256,
    _shouldUpdateTotal: bool,
):
    # update balances
    self.userBalances[_user][_asset] += _depositBal
    if _shouldUpdateTotal:
        self.totalBalances[_asset] += _depositBal

    # register user asset (if necessary)
    if self.indexOfUserAsset[_user][_asset] == 0:
        self._registerUserAsset(_user, _asset)

    # register vault asset (if necessary)
    if self.indexOfAsset[_asset] == 0:
        self._registerVaultAsset(_asset)


# withdrawal


@internal
def _reduceBalanceOnWithdrawal(
    _user: address,
    _asset: address,
    _withdrawBal: uint256,
    _shouldUpdateTotal: bool,
) -> (uint256, bool):
    assert self.indexOfUserAsset[_user][_asset] != 0 # dev: user does not have this asset

    currentBal: uint256 = self.userBalances[_user][_asset]
    withdrawBal: uint256 = min(_withdrawBal, currentBal)
    assert withdrawBal != 0 # dev: nothing to withdraw

    # update balances
    currentBal -= withdrawBal
    self.userBalances[_user][_asset] = currentBal
    if _shouldUpdateTotal:
        self.totalBalances[_asset] -= withdrawBal

    return withdrawBal, currentBal == 0


###############
# User Assets #
###############


@view
@external
def isUserInVaultAsset(_user: address, _asset: address) -> bool:
    return self.indexOfUserAsset[_user][_asset] != 0


@view
@external
def doesUserHaveBalance(_user: address, _asset: address) -> bool:
    return self.userBalances[_user][_asset] != 0


@internal
def _registerUserAsset(_user: address, _asset: address):
    aid: uint256 = self.numUserAssets[_user]
    if aid == 0:
        aid = 1 # not using 0 index
    self.userAssets[_user][aid] = _asset
    self.indexOfUserAsset[_user][_asset] = aid
    self.numUserAssets[_user] = aid + 1


@external
def deregisterUserAsset(_user: address, _asset: address) -> bool:
    assert msg.sender == addys._getLootboxAddr() # dev: only Lootbox allowed

    if self.userBalances[_user][_asset] != 0:
        return True

    numUserAssets: uint256 = self.numUserAssets[_user]
    if numUserAssets == 0:
        return False

    targetIndex: uint256 = self.indexOfUserAsset[_user][_asset]
    if targetIndex == 0:
        return numUserAssets > 1

    # update data
    lastIndex: uint256 = numUserAssets - 1
    self.numUserAssets[_user] = lastIndex
    self.indexOfUserAsset[_user][_asset] = 0

    # get last item, replace the removed item
    if targetIndex != lastIndex:
        lastItem: address = self.userAssets[_user][lastIndex]
        self.userAssets[_user][targetIndex] = lastItem
        self.indexOfUserAsset[_user][lastItem] = targetIndex

    return lastIndex > 1


################
# Vault Assets #
################


@view
@external
def isSupportedVaultAsset(_asset: address) -> bool:
    return self.indexOfAsset[_asset] != 0


@internal
def _registerVaultAsset(_asset: address):
    aid: uint256 = self.numAssets
    if aid == 0:
        aid = 1 # not using 0 index
    self.vaultAssets[aid] = _asset
    self.indexOfAsset[_asset] = aid
    self.numAssets = aid + 1


@external
def deregisterVaultAsset(_asset: address) -> bool:
    assert addys._isSwitchboardAddr(msg.sender) # dev: no perms

    if self.totalBalances[_asset] != 0:
        return False

    numAssets: uint256 = self.numAssets
    if numAssets == 0:
        return False

    targetIndex: uint256 = self.indexOfAsset[_asset]
    if targetIndex == 0:
        return False

    # update data
    lastIndex: uint256 = numAssets - 1
    self.numAssets = lastIndex
    self.indexOfAsset[_asset] = 0

    # get last item, replace the removed item
    if targetIndex != lastIndex:
        lastItem: address = self.vaultAssets[lastIndex]
        self.vaultAssets[targetIndex] = lastItem
        self.indexOfAsset[lastItem] = targetIndex

    return True


##############
# Data Utils #
##############


# any vault funds


@view
@external
def doesVaultHaveAnyFunds() -> bool:
    numAssets: uint256 = self.numAssets
    if numAssets == 0:
        return False
    for i: uint256 in range(1, numAssets, bound=max_value(uint256)):
        asset: address = self.vaultAssets[i]
        if self.totalBalances[asset] != 0:
            return True
    return False


# num user assets


@view
@external
def getNumUserAssets(_user: address) -> uint256:
    return self._getNumUserAssets(_user)


@view
@internal
def _getNumUserAssets(_user: address) -> uint256:
    numAssets: uint256 = self.numUserAssets[_user]
    if numAssets == 0:
        return 0
    return numAssets - 1


# num vault assets


@view
@external
def getNumVaultAssets() -> uint256:
    return self._getNumVaultAssets()


@view
@internal
def _getNumVaultAssets() -> uint256:
    numAssets: uint256 = self.numAssets
    if numAssets == 0:
        return 0
    return numAssets - 1


########
# Ripe #
########


# activate


@external
def pause(_shouldPause: bool):
    assert addys._isSwitchboardAddr(msg.sender) # dev: no perms
    assert _shouldPause != self.isPaused # dev: no change
    self.isPaused = _shouldPause
    log VaultPauseModified(isPaused=_shouldPause)


# recover funds


@external
def recoverFunds(_recipient: address, _asset: address):
    assert addys._isSwitchboardAddr(msg.sender) # dev: no perms
    self._recoverFunds(_recipient, _asset)


@external
def recoverFundsMany(_recipient: address, _assets: DynArray[address, MAX_RECOVER_ASSETS]):
    assert addys._isSwitchboardAddr(msg.sender) # dev: no perms
    for a: address in _assets:
        self._recoverFunds(_recipient, a)


@internal
def _recoverFunds(_recipient: address, _asset: address):
    assert empty(address) not in [_recipient, _asset] # dev: invalid recipient or asset
    balance: uint256 = staticcall IERC20(_asset).balanceOf(self)
    assert balance != 0 # dev: nothing to recover

    # cannot recover funds from a registered asset with a balance
    assert self.indexOfAsset[_asset] == 0 and self.totalBalances[_asset] == 0 # dev: invalid recovery

    assert extcall IERC20(_asset).transfer(_recipient, balance, default_return_value=True) # dev: recovery failed
    log VaultFundsRecovered(asset=_asset, recipient=_recipient, balance=balance)

contracts/vaults/modules/SharesVault.vy.content:
# Ripe Protocol License: https://github.com/ripe-foundation/ripe-protocol/blob/master/LICENSE.md
# Ripe Foundation (C) 2025

# @version 0.4.3

uses: vaultData
import contracts.vaults.modules.VaultData as vaultData

from interfaces import Vault
from ethereum.ercs import IERC20

DECIMAL_OFFSET: constant(uint256) = 10 ** 8


@deploy
def __init__():
    pass


########
# Core #
########


@internal
def _depositTokensInVault(
    _user: address,
    _asset: address,
    _amount: uint256,
) -> (uint256, uint256):
    assert not vaultData.isPaused # dev: contract paused

    # validation
    assert empty(address) not in [_user, _asset] # dev: invalid user or asset
    totalAssetBalance: uint256 = staticcall IERC20(_asset).balanceOf(self)
    depositAmount: uint256 = min(_amount, totalAssetBalance)
    assert depositAmount != 0 # dev: invalid deposit amount

    # calc shares
    prevTotalBalance: uint256 = totalAssetBalance - depositAmount # remove the deposited amount to calc shares accurately
    newShares: uint256 = self._amountToShares(depositAmount, vaultData.totalBalances[_asset], prevTotalBalance, False)

    # add balance on deposit
    vaultData._addBalanceOnDeposit(_user, _asset, newShares, True)

    return depositAmount, newShares


@internal
def _withdrawTokensFromVault(
    _user: address,
    _asset: address,
    _amount: uint256,
    _recipient: address,
) -> (uint256, uint256, bool):
    assert not vaultData.isPaused # dev: contract paused
    assert empty(address) not in [_user, _asset, _recipient] # dev: invalid user, asset, or recipient

    # calc shares + amount to withdraw
    withdrawalShares: uint256 = 0
    withdrawalAmount: uint256 = 0
    withdrawalShares, withdrawalAmount = self._calcWithdrawalSharesAndAmount(_user, _asset, _amount)

    # reduce balance on withdrawal
    isDepleted: bool = False
    withdrawalShares, isDepleted = vaultData._reduceBalanceOnWithdrawal(_user, _asset, withdrawalShares, True)

    # move tokens to recipient
    assert extcall IERC20(_asset).transfer(_recipient, withdrawalAmount, default_return_value=True) # dev: token transfer failed
    return withdrawalAmount, withdrawalShares, isDepleted


@internal
def _transferBalanceWithinVault(
    _asset: address,
    _fromUser: address,
    _toUser: address,
    _transferAmount: uint256,
) -> (uint256, uint256, bool):
    assert not vaultData.isPaused # dev: contract paused
    assert empty(address) not in [_fromUser, _toUser, _asset] # dev: invalid users or asset

    # calc shares + amount to transfer
    transferShares: uint256 = 0
    transferAmount: uint256 = 0
    transferShares, transferAmount = self._calcWithdrawalSharesAndAmount(_fromUser, _asset, _transferAmount)

    # transfer shares
    isFromUserDepleted: bool = False
    transferShares, isFromUserDepleted = vaultData._reduceBalanceOnWithdrawal(_fromUser, _asset, transferShares, False)
    vaultData._addBalanceOnDeposit(_toUser, _asset, transferShares, False)

    return transferAmount, transferShares, isFromUserDepleted


####################
# Needs For Others #
####################


@view
@internal
def _getVaultDataOnDeposit(_user: address, _asset: address) -> Vault.VaultDataOnDeposit:
    # used in Teller.vy
    totalBalance: uint256 = staticcall IERC20(_asset).balanceOf(self)
    return Vault.VaultDataOnDeposit(
        hasPosition=vaultData.indexOfUserAsset[_user][_asset] != 0,
        numAssets=vaultData._getNumUserAssets(_user),
        userBalance=self._getTotalAmountForUserWithTotalBal(_user, _asset, totalBalance),
        totalBalance=totalBalance,
    )


@view
@internal
def _getUserLootBoxShare(_user: address, _asset: address) -> uint256:
    # used in Lootbox.vy
    return vaultData.userBalances[_user][_asset] // DECIMAL_OFFSET


@view
@internal
def _getUserAssetAndAmountAtIndex(_user: address, _index: uint256) -> (address, uint256):
    # used in CreditEngine.vy
    asset: address = vaultData.userAssets[_user][_index]
    if asset == empty(address):
        return empty(address), 0
    userShares: uint256 = vaultData.userBalances[_user][asset]
    if userShares == 0:
        return empty(address), 0
    return asset, self._sharesToAmount(userShares, vaultData.totalBalances[asset], staticcall IERC20(asset).balanceOf(self), False)


@view
@internal
def _getUserAssetAtIndexAndHasBalance(_user: address, _index: uint256) -> (address, bool):
    # used in Lootbox.vy and AuctionHouse.vy
    asset: address = vaultData.userAssets[_user][_index]
    if asset == empty(address):
        return empty(address), False
    return asset, vaultData.userBalances[_user][asset] != 0


###############
# Other Utils #
###############


@view
@internal
def _getTotalAmountForUser(_user: address, _asset: address) -> uint256:
    return self._getTotalAmountForUserWithTotalBal(_user, _asset, staticcall IERC20(_asset).balanceOf(self))


@view
@internal
def _getTotalAmountForUserWithTotalBal(_user: address, _asset: address, _totalBalance: uint256) -> uint256:
    userShares: uint256 = vaultData.userBalances[_user][_asset]
    return self._sharesToAmount(userShares, vaultData.totalBalances[_asset], _totalBalance, False)


@view
@internal
def _getTotalAmountForVault(_asset: address) -> uint256:
    return staticcall IERC20(_asset).balanceOf(self)


##########
# Shares #
##########


@view
@internal
def _calcWithdrawalSharesAndAmount(
    _user: address,
    _asset: address,
    _amount: uint256,
) -> (uint256, uint256):
    totalBalance: uint256 = staticcall IERC20(_asset).balanceOf(self)
    assert totalBalance != 0 # dev: no asset to withdraw

    totalShares: uint256 = vaultData.totalBalances[_asset]

    # user shares
    withdrawalShares: uint256 = vaultData.userBalances[_user][_asset]
    assert withdrawalShares != 0 # dev: user has no shares

    # calc amount + shares to withdraw
    withdrawalAmount: uint256 = min(totalBalance, self._sharesToAmount(withdrawalShares, totalShares, totalBalance, False))
    if _amount < withdrawalAmount:
        withdrawalShares = min(withdrawalShares, self._amountToShares(_amount, totalShares, totalBalance, True))
        withdrawalAmount = _amount

    assert withdrawalAmount != 0 # dev: no withdrawal amount
    return withdrawalShares, withdrawalAmount


# amount -> shares


@view
@external
def amountToShares(_asset: address, _amount: uint256, _shouldRoundUp: bool) -> uint256:
    totalShares: uint256 = vaultData.totalBalances[_asset]
    totalBalance: uint256 = staticcall IERC20(_asset).balanceOf(self)
    return self._amountToShares(_amount, totalShares, totalBalance, _shouldRoundUp)


@view
@internal
def _amountToShares(
    _amount: uint256,
    _totalShares: uint256,
    _totalBalance: uint256,
    _shouldRoundUp: bool,
) -> uint256:
    totalBalance: uint256 = _totalBalance

    # dead shares / decimal offset -- preventing donation attacks
    totalBalance += 1
    totalShares: uint256 = _totalShares + DECIMAL_OFFSET

    # calc shares
    numerator: uint256 = _amount * totalShares
    shares: uint256 = numerator // totalBalance

    # rounding
    if _shouldRoundUp and (numerator % totalBalance != 0):
        shares += 1

    return shares


# shares -> amount


@view
@external
def sharesToAmount(_asset: address, _shares: uint256, _shouldRoundUp: bool) -> uint256:
    totalShares: uint256 = vaultData.totalBalances[_asset]
    totalBalance: uint256 = staticcall IERC20(_asset).balanceOf(self)
    return self._sharesToAmount(_shares, totalShares, totalBalance, _shouldRoundUp)


@view
@internal
def _sharesToAmount(
    _shares: uint256,
    _totalShares: uint256,
    _totalBalance: uint256,
    _shouldRoundUp: bool,
) -> uint256:
    totalBalance: uint256 = _totalBalance

    # dead shares / decimal offset -- preventing donation attacks
    totalBalance += 1
    totalShares: uint256 = _totalShares + DECIMAL_OFFSET

    # calc amount
    numerator: uint256 = _shares * totalBalance
    amount: uint256 = numerator // totalShares

    # rounding
    if _shouldRoundUp and (numerator % totalShares != 0):
        amount += 1

    return amount
